import { describe, expect, it } from 'vitest';
import {
  consumeDockEvidencePrefix,
  parseStoredMessage,
  restoreDockEvidenceForEdit,
} from './parseStoredMessage';
import type { ContextItem } from '$lib/components/chat/input/context-api';
import { DOCK_EVIDENCE_CONTEXT_HEADER } from '$shared/dock-evidence';

// Independent wire fixture: this is the stored-content contract, not a schema
// generated by the implementation being tested.
const header =
  '[Screen evidence: screenshots lead the attached images in this order; [[mark:n]] in the message refers to mark n; [[clip:n]] and [[clip:n:end]] mark where recording n started and stopped while the user was speaking]';
const body = {
  type: 'dock_screen_evidence',
  version: 1,
  images: [
    {
      image: 1,
      size: [2880, 1800],
      scale: 2,
      marks: [
        {
          n: 1,
          tool: 'box',
          geometry: { kind: 'rect', x: 10, y: 20, w: 30, h: 40 },
        },
      ],
    },
  ],
};
const block = (value: unknown = body) => `${header}\n\`\`\`json\n${JSON.stringify(value)}\n\`\`\``;

describe('stored screen evidence context', () => {
  it('refuses changed screenshot identity/order but permits removing an unrelated trailing image', () => {
    const context = parseStoredMessage(block()).contextItems[0];
    const screenshot: ContextItem = {
      id: 'screenshot',
      type: 'file',
      label: 'image',
      attachmentId: 'image-a',
      imageMimeType: 'image/png',
    };
    const unrelated: ContextItem = { ...screenshot, id: 'extra', attachmentId: 'image-b' };
    const original = [context, screenshot, unrelated];
    expect(
      restoreDockEvidenceForEdit(original, [context, unrelated, screenshot], 'Edited [[mark:1]]'),
    ).toBeNull();
    expect(
      restoreDockEvidenceForEdit(
        original,
        [context, { ...screenshot, attachmentId: 'replacement' }],
        'Edited',
      ),
    ).toBeNull();
    expect(restoreDockEvidenceForEdit(original, [context, screenshot], 'Edited [[mark:1]]')).toBe(
      `${block()}\n\nEdited [[mark:1]]`,
    );
    expect(restoreDockEvidenceForEdit(original, [screenshot], 'Edited')).toBe('Edited');
  });

  it('preserves ordinary user prose and system notices', () => {
    for (const text of [
      'Please fix this.',
      '[auto_unarchived]\nKeep this notice.',
      '```json\n{"version":1}\n```',
    ]) {
      expect(parseStoredMessage(text)).toEqual({ contextItems: [], userMessage: text });
    }
  });

  it('extracts evidence without changing the visible prompt or its references', () => {
    const prefix = block();
    const prompt = 'Fix [[mark:1]].\n\nKeep this second paragraph.';
    const parsed = parseStoredMessage(`${prefix}\n\n${prompt}`);
    expect(parsed.userMessage).toBe(prompt);
    expect(parsed.contextItems).toHaveLength(1);
    expect(parsed.contextItems[0]).toMatchObject({
      type: 'selection',
      content: prefix,
      metadata: { kind: 'dock_screen_evidence', version: 1 },
    });
    expect(consumeDockEvidencePrefix(`${prefix}\n\n${prompt}`)).toEqual({
      prefix,
      remaining: prompt,
    });
  });

  it('retains image-only evidence as context instead of losing the entire message', () => {
    const parsed = parseStoredMessage(block());
    expect(parsed.userMessage).toBe('');
    expect(parsed.contextItems[0].content).toBe(block());
  });

  it('supports clip-only context and does not require user text', () => {
    const prefix = block({
      type: 'dock_screen_evidence',
      version: 1,
      images: [],
      clip: {
        attachment_id: 'clip-attachment',
        duration_ms: 2400,
        has_mic_audio: false,
        mark_timestamps_ms: {},
      },
    });
    expect(consumeDockEvidencePrefix(prefix)).toEqual({ prefix, remaining: '' });
  });

  it('continues parsing existing context prefixes on either side', () => {
    const file = '[Currently viewing file: src/main.ts]\n```ts\nconst value = 1;\n```';
    const note = '[Currently viewing note: Plan]';
    const selection = '[Selected text:\n```\nold text\n```]';
    for (const prefixes of [
      [block(), file, note, selection],
      [file, note, selection, block()],
    ]) {
      const parsed = parseStoredMessage(`${prefixes.join('\n\n')}\n\nChange the highlighted part.`);
      expect(parsed.userMessage).toBe('Change the highlighted part.');
      expect(parsed.contextItems).toHaveLength(4);
      expect(parsed.contextItems.find((item) => item.path === 'src/main.ts')?.content).toBe(
        'const value = 1;',
      );
      expect(
        parsed.contextItems.find((item) => item.metadata?.kind === 'dock_screen_evidence')?.content,
      ).toBe(block());
      expect(parsed.contextItems.some((item) => item.content === 'old text')).toBe(true);
    }
  });

  it.each([
    ['unknown version', block({ ...body, version: 2 })],
    ['missing version', block({ images: body.images })],
    ['wrong type', block({ ...body, type: 'user_example' })],
    ['wrong image shape', block({ ...body, images: [{ image: 1 }] })],
    [
      'invalid geometry',
      block({
        ...body,
        images: [{ ...body.images[0], marks: [{ n: 1, tool: 'box', geometry: { kind: 'rect' } }] }],
      }),
    ],
    [
      'excess images',
      block({
        ...body,
        images: Array.from({ length: 5 }, (_, index) => ({
          ...body.images[0],
          image: index + 1,
          marks: [],
        })),
      }),
    ],
    ['empty evidence', block({ ...body, images: [] })],
    ['malformed JSON', `${header}\n\`\`\`json\n{not json}\n\`\`\``],
    ['multiline JSON', `${header}\n\`\`\`json\n${JSON.stringify(body, null, 2)}\n\`\`\``],
    ['different header', block().replace('Screen evidence:', 'Screen evidence example:')],
    ['wrong fence', block().replace('```json', '```javascript')],
    ['unterminated fence', block().slice(0, -3)],
    ['missing separator', `${block()}\nUser text`],
    ['closing fence suffix', `${block()}suffix`],
    ['non-prefix literal', `Example follows:\n\n${block()}`],
    ['quoted literal', `> ${block()}`],
    ['code-fenced literal', `\`\`\`text\n${block()}\n\`\`\``],
  ])('keeps %s as user text with established outer whitespace trimming', (_name, text) => {
    expect(consumeDockEvidencePrefix(text)).toBeNull();
    expect(parseStoredMessage(text)).toEqual({ contextItems: [], userMessage: text.trim() });
  });

  it('does not scan past invalid context into later user fences', () => {
    const text = `${header}\n\`\`\`json\n{invalid}\n\nUser prose\n\`\`\`\n\n${block()}`;
    expect(parseStoredMessage(text)).toEqual({ contextItems: [], userMessage: text });
  });

  it('leaves an oversized candidate intact', () => {
    const text = block({ ...body, extra: 'x'.repeat(262_144) });
    expect(consumeDockEvidencePrefix(text)).toBeNull();
    expect(parseStoredMessage(text)).toEqual({ contextItems: [], userMessage: text });
  });

  it('leaves a malformed evidence block intact after consuming an existing prefix', () => {
    const text = block({ ...body, version: 9 });
    const parsed = parseStoredMessage(`[Currently viewing: Spec]\n\n${text}`);
    expect(parsed.contextItems).toHaveLength(1);
    expect(parsed.userMessage).toBe(text);
  });

  it('keeps element strings inert, including escaped newlines, fences and markup', () => {
    const prefix = block({
      ...body,
      images: [
        {
          ...body.images[0],
          marks: [
            {
              ...body.images[0].marks[0],
              element: {
                role: 'button',
                name: '<img src=x onerror=alert(1)>\n```',
                path: null,
                source: null,
              },
            },
          ],
        },
      ],
    });
    const parsed = parseStoredMessage(`${prefix}\n\nDo not change <script>literal text</script>.`);
    expect(parsed.contextItems[0].content).toBe(prefix);
    expect(parsed.userMessage).toBe('Do not change <script>literal text</script>.');
  });
});

describe("the producer's current evidence block (recordings as a clips array)", () => {
  const current = {
    type: 'dock_screen_evidence',
    version: 1,
    images: [
      {
        image: 1,
        attachment_id: 'shot-1',
        size: [1440, 900],
        scale: 2,
        marks: [{ n: 1, tool: 'box', geometry: { kind: 'rect', x: 1, y: 2, w: 3, h: 4 } }],
      },
    ],
    clips: [
      {
        clip: 1,
        attachment_id: 'rec-1',
        duration_ms: 4000,
        has_mic_audio: true,
        mark_timestamps_ms: { '1': 900 },
      },
      {
        clip: 2,
        attachment_id: 'rec-2',
        duration_ms: 3000,
        has_mic_audio: false,
        mark_timestamps_ms: {},
      },
    ],
  };
  const wrap = (value: unknown) =>
    `${DOCK_EVIDENCE_CONTEXT_HEADER}\n\`\`\`json\n${JSON.stringify(value)}\n\`\`\``;

  it('is recognised from text alone and leaves only the words', () => {
    expect(consumeDockEvidencePrefix(`${wrap(current)}\n\nsee [[clip:2:end]]`)).toEqual({
      prefix: wrap(current),
      remaining: 'see [[clip:2:end]]',
    });
  });

  it('rejects misnumbered recordings from text alone', () => {
    const bad = { ...current, clips: [{ ...current.clips[1], clip: 2 }] };
    expect(consumeDockEvidencePrefix(wrap(bad))).toBeNull();
  });

  it('trusts the exact header + fence of a newer body only with the message metadata', () => {
    const newer = { type: 'dock_screen_evidence', version: 2, future: true };
    expect(consumeDockEvidencePrefix(`${wrap(newer)}\n\nhi`)).toBeNull();
    expect(consumeDockEvidencePrefix(`${wrap(newer)}\n\nhi`, { trusted: true })?.remaining).toBe(
      'hi',
    );
    // Even trusted, other JSON or a missing header is never consumed.
    expect(consumeDockEvidencePrefix(`${wrap({ type: 'other' })}`, { trusted: true })).toBeNull();
    expect(
      consumeDockEvidencePrefix('```json\n{"type":"dock_screen_evidence"}\n```', { trusted: true }),
    ).toBeNull();
    expect(parseStoredMessage(`${wrap(newer)}\n\nhi`, { trustedEvidence: true }).userMessage).toBe(
      'hi',
    );
  });
});
